request.schema:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "design_doc",
  "description": "How the change will be built, the API contract and the risks. Approved by a human before implementation.",
  "type": "object",
  "additionalProperties": false,
  "required": ["approach", "alternativesConsidered", "apiChanges", "schemaChanges", "components", "risks", "rolloutPlan"],
  "properties": {
    "approach": { "type": "string", "minLength": 1 },
    "alternativesConsidered": {
      "type": "array",
      "items": {
        "type": "object", "additionalProperties": false, "required": ["option", "whyNot"],
        "properties": { "option": { "type": "string" }, "whyNot": { "type": "string" } }
      }
    },
    "apiChanges": {
      "type": "string", "minLength": 1,
      "description": "An OpenAPI 3 fragment (YAML) for new or changed endpoints, or a sentence saying the API does not change."
    },
    "schemaChanges": { "type": "string", "description": "Flyway SQL for database changes; empty when there are none." },
    "components": {
      "type": "array", "minItems": 1,
      "items": {
        "type": "object", "additionalProperties": false, "required": ["name", "responsibility"],
        "properties": { "name": { "type": "string" }, "responsibility": { "type": "string" } }
      }
    },
    "risks": {
      "type": "array",
      "items": {
        "type": "object", "additionalProperties": false, "required": ["risk", "likelihood", "impact", "mitigation"],
        "properties": {
          "risk": { "type": "string" },
          "likelihood": { "enum": ["LOW", "MED", "HIGH"] },
          "impact": { "enum": ["LOW", "MED", "HIGH"] },
          "mitigation": { "type": "string" }
        }
      }
    },
    "rolloutPlan": { "type": "string", "minLength": 1 }
  }
}

response.text:
{
  "approach": "Destination rules live in UrlValidator, which every create already calls: after the self-reference check, the host (lower-cased, trailing dot removed) and each of its parent domains are looked up in the configured blocked domains sets, so www.evil.test matches evil.test but notevil.test does not. Refusals are InvalidUrlException with reason BLOCKED_DOMAIN (400 invalid-url, as today). Moderation: a new abuse package with AdminController (POST /api/v1/admin/links/{code}/flag, behind the existing API key interceptor; only keys named in shortener.abuse.admin-keys, else NotAdminException: 403 forbidden). LinkService.flag sets the new status FLAGGED (Flyway V3 widens the check constraint) and evicts the cache after commit; resolve answers 451 link-unavailable for a flagged row and never caches it.",
  "alternativesConsidered": [
    {
      "option": "An external reputation API (Safe Browsing)",
      "whyNot": "Ruled out in the answers: no external dependency on the create path."
    },
    {
      "option": "A blocklist table with an admin API",
      "whyNot": "More than needed now; configuration is reviewed and deployed like code. Can come later."
    },
    {
      "option": "Delete abusive links instead of flagging",
      "whyNot": "Deletion is the owner's action and answers 404; 451 tells clients why, and keeps the evidence."
    }
  ],
  "apiChanges": "paths:\n  /api/v1/links:\n    post:\n      responses:\n        '400': { description: 'invalid-url, reason BLOCKED_DOMAIN (new)' }\n  /api/v1/admin/links/{code}/flag:\n    post:\n      security: [ { apiKey: [] } ]\n      responses:\n        '204': { description: flagged (idempotent) }\n        '401': { description: unauthorized }\n        '403': { description: forbidden (not an admin key) }\n        '404': { description: link-not-found (unknown or deleted) }\n  /{code}:\n    get:\n      responses:\n        '451': { description: link-unavailable (flagged by an admin) }\n",
  "schemaChanges": "ALTER TABLE link DROP CONSTRAINT link_status_check;\nALTER TABLE link ADD CONSTRAINT link_status_check CHECK (status IN ('ACTIVE', 'DELETED', 'FLAGGED'));",
  "components": [
    {
      "name": "abuse.AbuseProperties",
      "responsibility": "shortener.abuse.blocked-domains (Set<String>, default empty), shortener.abuse.admin-keys (Set<String> of API key names, default empty). The application starts with the defaults."
    },
    {
      "name": "url.UrlValidator",
      "responsibility": "The blocked domains checks; the existing five-argument constructor stays (no rules)."
    },
    {
      "name": "abuse.AdminController / NotAdminException",
      "responsibility": "The flag endpoint and its 403."
    },
    {
      "name": "link.LinkService / Link / LinkStatus",
      "responsibility": "flag(code): FLAGGED and cache eviction after commit; resolve throws LinkUnavailableException (451) for FLAGGED."
    },
    {
      "name": "V3__link_flagged.sql",
      "responsibility": "Allows status FLAGGED."
    }
  ],
  "risks": [
    {
      "risk": "Constraint change on the link table",
      "likelihood": "LOW",
      "impact": "HIGH",
      "mitigation": "Small table; the new constraint is a superset of the old one, so every existing row passes."
    },
    {
      "risk": "A flagged link is served from a cache",
      "likelihood": "MED",
      "impact": "MED",
      "mitigation": "Evict after commit; the 451 is never cached; other instances' L1 bounded by its 5-minute TTL (documented)."
    },
    {
      "risk": "A blocklist entry is too broad",
      "likelihood": "LOW",
      "impact": "MED",
      "mitigation": "Exact domain-or-subdomain matching only, never substrings; the list is reviewed like code."
    }
  ],
  "rolloutPlan": "Migration V3 runs on startup. Ship with an empty blocklist and no admin keys, then set shortener.abuse.blocked-domains and shortener.abuse.admin-keys per environment. Rollback: redeploy the previous version after unflagging any FLAGGED rows (the old constraint rejects them)."
}
